package com.faraz.expensemanagement.controller; import com.faraz.expensemanagement.service.AppService; import com.faraz.expensemanagement.dto.Dtos; import org.springframework.web.bind.annotation.*; import java.util.Map; import java.util.List; @RestController @RequestMapping("/api") public class Api{final AppService s;Api(AppService x){s=x;}@PostMapping("/auth/register")Object register(@RequestBody Dtos.Register r){return s.register(r);}@PostMapping("/auth/login")Object login(@RequestBody Dtos.Login r){return s.login(r);}@GetMapping("/auth/me")Object me(){return s.dto(s.users.findByEmailIgnoreCase(org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow());}@GetMapping("/users/me")Object profile(){return me();}@GetMapping("/dashboard/summary")Object sum(){return s.summary();}@GetMapping("/dashboard/recent-transactions")Object recent(){return s.recent();}@GetMapping("/dashboard/monthly-overview")Object overview(){return Map.of("months",List.of());}@GetMapping("/dashboard/category-breakdown")Object breakdown(){return List.of();}@GetMapping("/transactions")Object tx(){return s.all();}@PostMapping("/transactions")Object create(@RequestBody Dtos.Tx r){return s.save(r,null);}@PutMapping("/transactions/{id}")Object update(@PathVariable Long id,@RequestBody Dtos.Tx r){return s.save(r,id);}@DeleteMapping("/transactions/{id}")void delete(@PathVariable Long id){s.delete(id);}@GetMapping("/categories")Object cats(){return s.categories();}@PostMapping("/categories")Object cat(@RequestBody Dtos.Category r){return s.saveCat(r);}@GetMapping("/budgets")Object budgets(){return s.budgetList();}@PostMapping("/budgets")Object budget(@RequestBody Dtos.Budget r){return s.saveBudget(r);}@GetMapping("/reports/monthly")Object report(){return s.summary();}}